66	// listAllSessionStates returns all active session states.
67	// It filters out orphaned sessions whose shadow branch no longer exists.
68	func (s *ManualCommitStrategy) listAllSessionStates(ctx context.Context) ([]*SessionState, error) {
69		store, err := s.getStateStore(ctx)
70		if err != nil {
71			return nil, fmt.Errorf("failed to get state store: %w", err)
72		}
73	
74		sessionStates, err := store.List(ctx)
75		if err != nil {
76			return nil, fmt.Errorf("failed to list session states: %w", err)
77		}
78	
79		if len(sessionStates) == 0 {
80			return nil, nil
81		}
82	
83		repo, err := OpenRepository(ctx)
84		if err != nil {
85			return nil, fmt.Errorf("failed to open git repository: %w", err)
86		}
87		defer repo.Close()
88	
89		var states []*SessionState
90		for _, sessionState := range sessionStates {
91			state := sessionState
92			// Adopted-away source records are tombstones: keep them until normal stale
93			// expiry so old source hooks cannot recreate a second live state.
94			if state.AdoptedIntoWorktreePath != "" {
95				states = append(states, state)
96				continue
97			}
98	
99			// Imported sessions are read-only historical records: no shadow branch
100			// and (by design) no BaseCommit. Keep them regardless of the
101			// shadow-branch orphan check below. Gate on Kind, not on commit
102			// presence, so this stays correct once imports are linked to a commit.
103			if state.Kind.IsImported() {
104				states = append(states, state)
105				continue
106			}
107	
108			// Skip and cleanup orphaned sessions whose shadow branch no longer exists.
109			// Keep active sessions (shadow branch may not be created yet) and sessions
110			// with LastCheckpointID (needed for checkpoint ID reuse on subsequent commits).
111			// Clean up everything else: stale pre-state-machine sessions (empty phase),
112			// IDLE/ENDED sessions that were never condensed, etc.
113			shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
114			refName := plumbing.NewBranchReferenceName(shadowBranch)
115			if _, err := repo.Reference(refName, true); err != nil {
116				if !state.Phase.IsActive() && state.LastCheckpointID.IsEmpty() {
117					//nolint:errcheck,gosec // G104: Cleanup is best-effort, shouldn't fail the list operation
118					store.Clear(ctx, state.SessionID)
119					continue
120				}
121			}
122	
123			states = append(states, state)
124		}
125		return states, nil
126	}
