128	// isWarnableStaleEndedSession reports whether an ENDED session is still both
129	// expensive in PostCommit and actionable via 'entire doctor'.
130	func isWarnableStaleEndedSession(repo *git.Repository, state *SessionState) bool {
131		if state.Phase != session.PhaseEnded || state.FullyCondensed || state.StepCount <= 0 {
132			return false
133		}
134	
135		// Re-check shadow branch existence even though listAllSessionStates already
136		// filters orphaned sessions. This is intentional: PostCommit deletes shadow
137		// branches during condensation, so a branch that existed at list-load time
138		// may be gone by the time we reach the warning check. Without this re-check
139		// we would warn about sessions that this commit just cleaned up.
140		shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
141		refName := plumbing.NewBranchReferenceName(shadowBranch)
142		_, err := repo.Reference(refName, true)
143		return err == nil
144	}
